package shop.ultimatesmp.network;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;
class BridgeTest {
 @Test void framesRoundTripAndRejectBadInputs(){UUID id=UUID.randomUUID();Wire f=Wire.of("COMMAND",id,"tpr",".Bedrock_Name");assertEquals(f,Wire.decode(f.encode()));byte[] bad=f.encode();bad[0]=0;assertThrows(IllegalArgumentException.class,()->Wire.decode(bad));assertThrows(IllegalArgumentException.class,()->Wire.decode(new byte[30001]));assertThrows(IllegalArgumentException.class,()->Wire.decode(new byte[0]));assertThrows(IllegalArgumentException.class,()->Wire.of("bad-kind",id));assertThrows(IllegalArgumentException.class,()->Wire.of("COMMAND",id,"a".repeat(4097)));assertThrows(IllegalArgumentException.class,()->Wire.of("COMMAND",id,"bad\0value"));byte[] trailing=Arrays.copyOf(f.encode(),f.encode().length+1);assertThrows(IllegalArgumentException.class,()->Wire.decode(trailing));}
 @Test void sourceMustBeCurrentAuthenticatedCarrier(){UUID id=UUID.randomUUID();assertTrue(Wire.authentic(id,id,"one","one"));assertFalse(Wire.authentic(id,UUID.randomUUID(),"one","one"));assertFalse(Wire.authentic(id,id,"one","two"));assertFalse(Wire.authentic(id,id,null,null));}
 @Test void consentIsRecipientBoundAndExpires(){Requests r=new Requests();UUID a=UUID.randomUUID(),b=UUID.randomUUID(),other=UUID.randomUUID();r.send(a,b,"tpa",10000);assertThrows(IllegalArgumentException.class,()->r.take(other,a,"tpa",10001));assertThrows(IllegalArgumentException.class,()->r.take(b,a,"trade",10001));assertEquals(a,r.take(b,a,"tpa",10001).mover());assertThrows(IllegalArgumentException.class,()->r.take(b,a,"tpa",10002));r.send(a,b,"here",20000);assertEquals(b,r.take(b,a,"tpa",20001).mover());r.send(a,b,"tpa",30000);assertThrows(IllegalArgumentException.class,()->r.take(b,a,"tpa",60000));}
 @Test void requestsBoundSpamAndDisconnect(){Requests r=new Requests();UUID a=UUID.randomUUID(),b=UUID.randomUUID();assertThrows(IllegalArgumentException.class,()->r.send(a,a,"tpa",0));r.send(a,b,"trade",10000);assertThrows(IllegalArgumentException.class,()->r.send(a,b,"trade",10001));r.leave(b);assertEquals(0,r.size());for(int i=0;i<5;i++)r.send(UUID.randomUUID(),b,"tpa",20000);assertThrows(IllegalArgumentException.class,()->r.send(UUID.randomUUID(),b,"tpa",20001));r.expire(50000);assertEquals(0,r.size());}
 @Test void aliasesDoNotExpandAuthority(){assertEquals("tpr",Commands.canonical("ultimate:tpa"));assertEquals("msg",Commands.canonical("minecraft:tell"));assertEquals("ultimateranks.command.tp",Commands.permission("tp"));assertEquals("ultimatetpr.use",Commands.permission("tprhere"));assertEquals(0,Commands.level("ULTIMATE_PLUS_PLUS"));assertEquals(7,Commands.level("OWNER"));assertTrue(Commands.routed("msg"));assertFalse(Commands.routed("op"));assertFalse(Commands.routed("stop"));assertFalse(Commands.routed("tprUnknown"));}
}
